    title: "計算③ 理論の深掘り（座標系・誤差・トラバース・求積の根拠）",
    body: `
<p>計算は手順の暗記でも解けるが、<b>理論</b>を理解すると検算力と応用力が段違いになる。座標系・誤差・トラバース・求積の「なぜ」を押さえる。</p>

<h4>1. 平面直角座標系 — 地球を平面に写す</h4>
<ul>
<li>日本全国を<b>19の座標系</b>に分け、各系の原点を基準に<b>X＝真北方向（北が＋）、Y＝東方向（東が＋）</b>で表す（数学のx・yと縦横が逆）。</li>
<li>測地基準は<b>世界測地系（JGD2011）</b>。だから座標値は原点から±数千〜数万mの大きな符号付きの値になる。</li>
<li>方向角Tは<b>北（X軸正方向）から時計回り</b>。ΔX＝S·cosT、ΔY＝S·sinT。三角関数の役割がXとYで「数学と逆」になる点に注意。</li>
</ul>

<h4>2. 誤差論 — 観測値は必ずズレる</h4>
<table class="simple">
<tr><th>誤差の種類</th><th>性質と対処</th></tr>
<tr><td>過失（ミステイク）</td><td>読み間違い等。<b>除去すべきで誤差ではない</b></td></tr>
<tr><td>系統誤差（定誤差）</td><td>器械の癖等で一定方向。補正・較正で消す</td></tr>
<tr><td>偶然誤差</td><td>避けられない微小なばらつき。<b>最確値（平均）・最小二乗</b>で処理</td></tr>
</table>
<div class="why">トラバースの「閉合差を配分する」のは偶然誤差を各測線へ合理的に割り振る作業。距離に比例＝<b>コンパス法</b>、緯距経距の絶対値に比例＝<b>トランシット法</b>、等分＝均等法。</div>

<h4>3. トラバース測量の理論</h4>
<ul>
<li><b>結合トラバース</b>＝既知点Aから既知点Bへ。<b>閉合トラバース</b>＝出発点へ戻る多角形。</li>
<li><b>角度閉合差</b>＝観測角の和と理論値（閉合多角形の内角和＝(n−2)×180°等）の差 → 各角へ配分。</li>
<li><b>座標閉合差</b>（ΔX, ΔY）＝緯距和・経距和の不一致 → 配分。<b>閉合比＝閉合距離 ÷ 全測線長</b>（小さいほど精度が高い）。</li>
</ul>

<h4>4. 求積の理論 — ガウスの面積公式（座標法）</h4>
<ul>
<li>多角形の面積は、各頂点の座標から <b>2S＝Σ(Xᵢ·Yᵢ₊₁ − Xᵢ₊₁·Yᵢ)</b>（靴ひも公式）で求まる。<b>ΣXᵢ(Yᵢ₊₁−Yᵢ₋₁)</b> も同値。</li>
<li>これは「各辺と座標軸が作る台形面積の符号付き総和」。閉じた多角形では平行移動で値が変わらない（<b>座標差で計算するから世界測地系の大座標でも桁落ちしにくい</b>）。</li>
<li><b>三斜法</b>（三角形に分割）・<b>三辺法</b>（三辺から面積）も原理は同じ「三角形の面積の積み上げ」。</li>
</ul>

<h4>5. 端数処理の根拠と関数電卓</h4>
<ul>
<li><b>地積</b>（規則100条）: 宅地・鉱泉地は0.01㎡単位、その他は10㎡超で1㎡単位、いずれも<b>切捨て</b>。<b>床面積</b>（規則115条）: 1/100㎡未満<b>切捨て</b>。</li>
<li><b>Pol/Rec</b> は極座標⇄直交座標の変換そのもの。<b>Pol(ΔX,ΔY)＝(距離, 方向角)</b>、<b>Rec(S,T)＝(ΔX, ΔY)</b>。逆計算・放射・トラバースが一発で回る理論的理由。</li>
</ul>

<h4>6. 確認問題</h4>
<div class="drill">次の記述の正誤を答えよ。
<ol>
<li>閉合トラバース測量における閉合誤差は、系統誤差であるから配分してはならない。</li>
<li>コンパス法則による閉合差の配分は、各測線の距離に比例して行う。</li>
<li>座標法（靴ひも公式）による面積計算では、座標の原点をどこに取っても求まる面積は変わらない。</li>
<li>公差は、国土調査法施行令別表第四の精度区分ごとに定められ、面積が大きいほど許容される誤差も大きくなる。</li>
<li>地積の端数処理は切捨てであるが、床面積の端数処理は四捨五入である。</li>
</ol>
<details><summary>解答と解説を見る</summary>
<p><b>1 ── 誤り。</b>閉合誤差は主として<b>偶然誤差</b>の累積であり、一定の法則（コンパス法則等）に従って<b>配分する</b>。</p>
<p><b>2 ── 正しい。</b>コンパス法則は<b>距離に比例</b>して配分する（トランシット法則は緯距・経距の絶対値に比例）。</p>
<p><b>3 ── 正しい。</b>座標法は<b>座標の差</b>で計算するため、原点の取り方に影響されない。任意座標でも正しい面積が出る。</p>
<p><b>4 ── 正しい。</b>公差は (a + b×⁴√F)×√F の形で、面積Fが大きいほど値が大きくなる。</p>
<p><b>5 ── 誤り。</b><b>どちらも切捨て</b>である。地積は規則100条、床面積は規則115条による。</p>
</details>
</div>

<div class="pt">計算理論カード: <b>X北Y東・方向角は北から時計回り</b>／<b>偶然誤差を配分（コンパス＝距離比例）</b>／<b>面積は靴ひも公式（座標差で安定）</b>／<b>地積・床面積は切捨て</b>／<b>Pol/Recは極⇄直交変換</b>。理屈が分かると検算が速い。</div>`,
