    title: "土地⑫ 地図・地番（必修・14条地図と公図の違い）",
    body: `
<div class="pt"><b>この講義の結論</b><br>
① <a class="art" data-art="不登法14">法14条</a>1項の<b>地図</b>は<b>現地復元能力</b>を持つ。<b>地図に準ずる図面（公図）</b>は持たない<br>
② 地図が備え付けられるまでの間は、公図を備え付けることが<b>できる</b><br>
③ 地図の誤りを直すのは<b>「申出」</b>であって登記の申請ではない<br>
④ <b>地番は登記官が付する</b>。申請人に指定権はない<br>
⑤ 分筆は<b>支号</b>（5番→5番1・5番2）、合筆は<b>首位の地番</b>を使う<br>
⑥ 行政区画・字の名称が変わったら<b>変更の登記があったものとみなされる</b>（申請不要）</div>

<h4>1. 14条地図と公図 — 決定的な違い</h4>
<table class="simple">
<tr><th></th><th>法14条1項の地図</th><th>地図に準ずる図面（公図）</th></tr>
<tr><td>現地復元能力</td><td><b>ある</b></td><td><b>ない</b></td></tr>
<tr><td>測地系</td><td>原則<b>世界測地系</b></td><td>基準が不統一</td></tr>
<tr><td>成り立ち</td><td>地籍調査の成果・登記所の測量等</td><td>旧土地台帳附属地図など</td></tr>
<tr><td>位置づけ</td><td>正規の地図</td><td>地図が備わるまでの<b>暫定</b></td></tr>
</table>
<div class="why"><b>現地復元能力</b>とは、図面の数値から現地に境界標を打ち直せる能力のことである。<br>
14条地図は<b>国家基準点に基づく座標</b>で各筆界点の位置が決まっているので、図面が失われても現地を復元できる。<br>
公図は明治期の測量などが元になっており、形状の概略は分かっても座標がない。だから復元できない。<b>「座標があるか」</b>が本質的な差である。</div>
<div class="ex">地図は、一筆又は二筆以上の土地ごとに作成し、各土地の<b>区画を明確にし、地番を表示</b>する。<br>
記録事項には、図郭線及びその座標値、基本三角点等の位置、精度区分のほか<b>縮尺係数</b>が含まれる。</div>
<table class="simple">
<tr><th>地域</th><th>地図の縮尺（原則）</th></tr>
<tr><td>市街地地域</td><td><b>250分の1</b>又は<b>500分の1</b></td></tr>
</table>

<h4>2. 地図の訂正は「申出」</h4>
<p><b>結論</b>——地図又は地図に準ずる図面に誤りがあるときの訂正は、<b>登記の申請ではなく「申出」</b>である（地図訂正等申出）。</p>
<div class="why">地図は<b>登記官が職権で作成・管理する</b>ものであって、当事者が申請して作らせるものではない。だから当事者にできるのは<b>「誤っていますよ」と申し出ること</b>までで、直すかどうかは登記官が判断する。<br>
登記の申請なら却下・取下げという処理になるが、申出にはそれがない——手続の性質が違う点が問われる。</div>
<table class="simple">
<tr><th>論点</th><th>結論</th></tr>
<tr><td>訂正の性質</td><td><b>申出</b>（登記の申請ではない）</td></tr>
<tr><td>土地所在図・地積測量図の提供が要る場合</td><td>土地の<b>区画・位置・形状</b>に誤りがあるとき</td></tr>
<tr><td>地積を変更したいとき</td><td>地図訂正ではなく<b>地積の更正の登記</b></td></tr>
</table>
<div class="trap">「地図の面積と登記地積が違うから地図訂正の申出をする」は誤り。<b>地積は登記記録の事項</b>なので、直すのは地積更正の登記である。<b>地図で直せるのは区画・位置・形状</b>と押さえる。</div>

<h4>3. 地番は登記官が付する</h4>
<p><b>結論</b>——地番は<b>登記官が</b>、地番区域ごとに、一筆の土地ごとに付する。<b>申請人が指定することはできない</b>。</p>
<table class="simple">
<tr><th>場面</th><th>地番の付け方</th></tr>
<tr><td><b>分筆</b></td><td>元の地番に<b>支号</b>を付ける（5番 → 5番1・5番2）</td></tr>
<tr><td><b>合筆</b></td><td><b>首位の地番</b>を用いる</td></tr>
<tr><td>合筆で閉鎖された地番</td><td>特別の事情がない限り<b>再使用しない</b></td></tr>
</table>
<div class="ex">支号の支号を用いた地番（5番1の1など）であっても、<b>申請情報の内容は登記記録に記録されているとおり</b>とする。申請後に登記官が職権で地番を変更することはあっても、申請人が勝手に書き換えるのではない。</div>
<div class="trap">同一の地番区域内の二筆に<b>同一の地番が重複</b して定められているとき、<b>後に登記された土地の登記記録を閉鎖する</b>のではない。地番の重複は<b>地番の変更</b>で処理すべき問題であり、登記記録を閉鎖する話ではない。</div>

<h4>4. 行政区画の変更</h4>
<p><b>結論</b>——行政区画・字又はその名称に変更があったときは、<b>変更の登記があったものとみなされる</b>。当事者の申請を要しない。</p>
<div class="why">市町村合併で「◯◯町」が「△△市」になったとする。該当する土地は数万筆にのぼる。これを所有者に一件ずつ申請させるのは不合理である。<br>
だから<b>法律上当然に変更があったものとみなす</b>。同じ発想は建物所在図にもあり、行政区画の変更は所在図に記録した行政区画にも及ぶ。</div>

<h4>5. 国土調査（地籍調査）と登記</h4>
<p><b>結論</b>——地籍調査の成果（<b>地籍簿・地籍図</b>）の写しが登記所へ送付されると、<b>登記官が職権で登記</b>し、地籍図は<b>14条1項の地図として備え付け</b>られる。</p>
<div class="why">地籍調査は<b>国が測量して一筆ごとの境界と面積を明らかにする</b>事業である。その成果は精度が高く座標を伴うので、そのまま14条地図の要件を満たす。<br>
当事者が申請しなくても登記官が職権で処理するのは、成果が公的に確定しているからである。</div>
<div class="pt">地図を作成するための一筆地測量及び地積測定の<b>誤差の限度（公差）</b>は、地域ごとに使える精度区分の上限が決まっている。村落・農耕地域は<b>乙一まで</b>、市街地地域は<b>甲二まで</b>、山林・原野地域は<b>乙三まで</b>である。</div>

<h4>6. 本試験ではこう出る</h4>
<p><b>択一</b>——14条地図と公図の対比が最頻出で、「公図にも現地復元能力がある」という誤りの肢が定番。地図訂正が「申出」であることと、地番を登記官が付することも繰り返し出る。</p>
<p><b>記述</b>——直接の出題は少ないが、<b>公差</b>の判断（求積値と登記地積の差が公差の範囲内なら地積更正を申請しない）で精度区分が使われる。</p>

<div class="pt"><b>地図・地番カード</b><br>
① <b>14条地図＝現地復元能力あり／公図＝なし</b>（座標があるかどうか）<br>
② 地図が備わるまでは<b>公図を備え付けられる</b><br>
③ 地図の訂正は<b>申出</b>。地積を直すなら<b>地積更正の登記</b><br>
④ <b>地番は登記官が付する</b>。分筆は支号・合筆は首位の地番<br>
⑤ 閉鎖された地番は<b>再使用しない</b><br>
⑥ 行政区画の変更は<b>みなし変更</b>（申請不要）<br>
⑦ 地籍調査の成果は<b>職権で登記</b>され地籍図は14条地図になる</div>
`,
